   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="也许是见你们长时间不出来，露可从外面进来跳上了床，猫不太理解人类的行为，蹲在那儿好奇地注视着你们。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
