   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女手忙脚乱地推开你，气呼呼地起身跳下床，把一脸迷惑的猫抱起来，走出门放下，回身锁门，动作一气呵成。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [184]={next_id=185, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看到你笑，她理了理有点凌乱的头发，回来压着你躺下，神情颇为得意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [185]={next_id=186, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哼哼，露可别想进来捣乱了，汝也不许出去。", msg_color="", msg_size=0, talker="珂芙尼尔", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4524", 0, 0, -38, 208}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她抱得有点紧，你觉得胸口有点沉重和呼吸不畅，就像之前露可压住你时那样——不过这次取代露可位置的变成了世界第一的魔法少女，而她的心意比什么都要紧。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1504.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
